      "evidence_locator_ids": [
        "S12-E01",
        "S12-E02",
        "S12-E05",
        "S12-E06"
      ],
      "interpretation": "Batch sorption/removal of precursor PFAS (PFEA, sulfonamides, sulfonamide acetic acids) from tap water onto GAC at ~5 ng/L, expressed qualitatively as higher or lower sorption relative to other PFAS groups. This is adsorption (phase transfer), not chemical degradation.",
      "reported_term": "sorption of PFAS precursors onto GAC; PFAS precursor removal"
    },
    {
      "endpoint_type": "other",
      "evidence_locator_ids": [
        "S12-E06",
        "S12-E08"
      ],
      "interpretation": "No clear relation between sorption and carbon chain length was observed for PFEA and sulfonamides within the limited chain-length range tested. Ether linkages and sulfonamide groups enhanced sorption, and C8 sulfonamide acetic acids (EtFOSAA and MeFOSAA) exhibited higher sorption than PFCA of similar chain length (C9).",
      "reported_term": "chain-length and functional-group effects for PFAS precursors"
    },
    {
      "endpoint_type": "other",
      "evidence_locator_ids": [
        "S12-E08"
      ],
      "interpretation": "Branched isomers of sulfonamide acetic acids showed significantly higher sorption than their linear counterparts (p < 0.05), attributed to changes in hydrophobic tail geometry and resulting electrostatic interactions of the functional groups with GAC.",
      "reported_term": "branching effects in sulfonamide acetic acids"
    },
    {
      "endpoint_type": "other",
      "evidence_locator_ids": [
        "S12-E02",
        "S12-E03",
        "S12-E05",
        "S12-E06",
        "S12-E08"
      ],
      "interpretation": "Overall sorption of PFAS precursors to GAC is explained by combined hydrophobic and electrostatic interactions, with sulfonamide and ether functionalities increasing affinity; additional electrostatic interactions in sulfonamide acetic acids (sulfonamide plus carboxylic group) enhance sorption compared to analogous PFCA.",
      "reported_term": "sorption mechanism for precursors"
    }
  ],
